describe('User Profile Language Preference', () => {
    beforeEach(() => {
        cy.visit('/profile/settings');
        cy.login(); // Assuming there's a custom command for login
    });

    it('should allow the user to set their language preference to English', () => {
        cy.get('select[name="language"]').select('English');
        cy.get('button[type="submit"]').click();
        cy.get('.notification').should('contain', 'Language preference updated successfully');
        cy.get('select[name="language"]').should('have.value', 'English');
    });

    it('should display an error when an invalid language is selected', () => {
        cy.get('select[name="language"]').select('InvalidLanguage');
        cy.get('button[type="submit"]').click();
        cy.get('.error').should('contain', 'Invalid language selection');
        cy.get('select[name="language"]').should('not.have.value', 'InvalidLanguage');
    });
});
